from state import LRUCache

def test_lru_evicts_least_recently_used():
    c = LRUCache(2)
    c.put("a", 1)
    c.put("b", 2)
    assert c.get("a") == 1
    c.put("c", 3)
    assert c.get("a") == 1
    assert c.get("b") is None

def test_lru_missing():
    assert LRUCache(2).get("x") is None


from collect import group_by

def test_group_calls_independent():
    a = group_by([1, 2], lambda x: x % 2)
    b = group_by([10], lambda x: x % 2)
    assert a == {1: [1], 0: [2]}
    assert b == {0: [10]}

def test_group_empty():
    assert group_by([], lambda x: x) == {}
